per_hop.query:
SELECT ?otherFilm ?otherFilmReleaseDate WHERE {
  ?sacredPlanet wdt:P31 wd:Q11424; # instance of film
               rdfs:label "Sacred Planet"@en;
               wdt:P577 ?sacredPlanetReleaseDate.

  ?otherFilm wdt:P31 wd:Q11424;
             wdt:P161 ?actor;
             wdt:P577 ?otherFilmReleaseDate.

  ?actor rdfs:label "Damion Poitier"@en.

  FILTER(?otherFilmReleaseDate < ?sacredPlanetReleaseDate)
} ORDER BY DESC(?otherFilmReleaseDate)

SELECT ?otherFilm ?otherFilmReleaseDate WHERE {
  ?sacredPlanet wdt:P31 wd:Q11424; # instance of film
               rdfs:label "Sacred Planet"@en;
               wdt:P577 ?sacredPlanetReleaseDate.

  ?otherFilm wdt:P31 wd:Q11424;
             wdt:P161 ?actor;
             wdt:P577 ?otherFilmReleaseDate.

  ?actor rdfs:label "Damion Poitier"@en.

  FILTER(?otherFilmReleaseDate < ?sacredPlanetReleaseDate)
} ORDER BY DESC(?otherFilmReleaseDate)

SELECT ?actor WHERE {
  ?show1 wdt:P31 wd:Q838948;  # "Hollywood Goes Classical" as a performance
         wdt:P364 wd:Q1860.    # Location: Dorothy Chandler Pavilion (verify QID)
  ?actor wdt:P106 wd:Q33999;   # occupation: actor
         wdt:P27 wd:Q186;      # nationality: English (UK)
         wdt:P161 ?show1.
  ?film wdt:P31 wd:Q11424;     # instance of: film
        rdfs:label "Lethal Obsession"@en;
        wdt:P161 ?actor.
}
